  const icons={home:'M3 10.5 12 3l9 7.5V21H3z M9 21v-7h6v7',wallet:'M3 6h16v14H3z M3 6V4h15 M15 12h6v5h-6z',trophy:'M7 3h10v6a5 5 0 0 1-10 0z M7 5H3v3a4 4 0 0 0 4 4 M17 5h4v3a4 4 0 0 1-4 4 M12 14v5 M8 21h8',flag:'M4 22V3 M4 4h15l-3 5 3 5H4',gauge:'M4 18a9 9 0 1 1 16 0 M12 13l5-5 M9 19h6',users:'M16 20v-2a4 4 0 0 0-4-4H7a4 4 0 0 0-4 4v2z M9.5 10a3 3 0 1 0 0-6 3 3 0 0 0 0 6 M16 4a3 3 0 0 1 0 6 M20 20v-2a4 4 0 0 0-3-3.9',tag:'M3 4h9l9 9-8 8-10-10z M8 8h.01',grid:'M3 3h8v8H3z M13 3h8v8h-8z M3 13h8v8H3z M13 13h8v8h-8z',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M4 21a8 8 0 0 1 16 0',mail:'M3 5h18v14H3z M3 6l9 8 9-8',play:'M8 5l11 7-11 7z',sun:'M12 3v2 M12 19v2 M3 12h2 M19 12h2 M5.6 5.6 7 7 M17 17l1.4 1.4 M5.6 18.4 7 17 M17 7l1.4-1.4 M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8',menu:'M4 6h16 M4 12h16 M4 18h16',arrow:'M4 12h16 M14 6l6 6-6 6',info:'M12 17v-6 M12 7h.01 M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',close:'M5 5l14 14 M19 5L5 19',download:'M12 3v12 M7 10l5 5 5-5 M4 19h16',copy:'M8 8h12v13H8z M4 16V4h12'};
  const escapeHtml=(value)=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.info}"/></svg>`;
  const link=(route,label,kind='secondary')=>`<a class="button ${kind}" href="#${route}">${label}</a>`;
  const eyebrow=(text)=>`<div class="eyebrow">${text}</div>`;
  const head=(section,title,desc,aside='')=>`<header class="page-header"><div>${eyebrow(section)}<h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${aside?`<div class="header-aside">${aside}</div>`:''}</header>`;
  const panel=(title,body,more='')=>`<section class="panel"><div class="panel-title"><h2>${title}</h2>${more}</div>${body}</section>`;
  const notice=(type,title,body)=>`<div class="notice ${type}">${icon('info')}<div><strong>${title}</strong>${body}</div></div>`;
  const badge=(text,type='')=>`<span class="badge ${type}">${text}</span>`;
