  const states=(route)=>`<section class="screen-states" aria-label="Estados de muestra de ${routes[route][0]}"><h2>Estados de esta pantalla</h2><div class="screen-states-grid"><div><span class="eyebrow">CARGANDO</span><div class="skeleton" aria-label="Cargando contenido"></div><small>Esperando datos de muestra.</small></div><div><span class="eyebrow">SIN DATOS</span><p>Aún no hay contenido registrado para esta vista.</p></div><div><span class="eyebrow">ERROR</span><p>No se pudo cargar esta vista. No se muestran cifras inventadas.</p></div></div></section>`;
