  const login=()=>`<div class="auth auth-editorial"><div class="auth-intro"><span class="eyebrow">F1 BUGAMBRA / ACCESO</span><span class="auth-index">01 / PADDOCK</span><h1>La temporada<br>empieza aquí.</h1><p>Una entrada sencilla a tu escudería, las carreras y la conversación del paddock.</p><span class="auth-footnote">TEMPORADA DE MUESTRA · DATOS FICTICIOS</span></div><div class="auth-form"><div id="auth-switch">${tabs([['login','Entrar'],['registro','Registrarme']],current())}</div><h2 id="auth-title">${current()==='registro'?'Crear cuenta.':'Bienvenido.'}</h2><p class="muted small">Acceso de muestra. No se envía ningún dato.</p><button class="google-button" type="button" data-demo="google-auth"><span class="google-mark" aria-hidden="true">G</span>Continuar con Google</button><div class="auth-divider"><span>O CONTINUAR CON CORREO</span></div><form id="auth-form"><label class="field" id="name-field" ${current()==='registro'?'':'hidden'}>Nombre visible<input type="text" autocomplete="name" placeholder="Tu nombre"></label><label class="field">Correo electrónico<input type="email" autocomplete="email" required placeholder="tú@ejemplo.com"></label><label class="field">Contraseña<input type="password" autocomplete="${current()==='registro'?'new-password':'current-password'}" required placeholder="••••••••"></label><button class="button full" type="submit" id="auth-submit">${current()==='registro'?'Registrarme':'Entrar'} (demo) →</button></form><a class="inline-link" href="#inicio">Explorar sin cuenta →</a></div></div>`;
  const install=()=>`${head('INSTALAR','Lleva el paddock contigo.','La app web puede quedar a un toque de distancia. Estos pasos son una vista de concepto, no instalan nada por sí solos.')}<div class="grid two">${panel('En iPhone / Safari',`<div class="steps"><div class="step"><div><h3>Abre el sitio en Safari</h3><p>Usa la dirección oficial cuando esté disponible.</p></div></div><div class="step"><div><h3>Toca Compartir</h3><p>Busca «Añadir a pantalla de inicio».</p></div></div><div class="step"><div><h3>Confirma el acceso</h3><p>El icono quedará junto a tus apps.</p></div></div></div>`)}${panel('En Android / Chrome',`<div class="steps"><div class="step"><div><h3>Abre el sitio en Chrome</h3><p>Espera a que se cargue la portada.</p></div></div><div class="step"><div><h3>Abre el menú</h3><p>Elige «Instalar aplicación» o «Añadir a pantalla de inicio».</p></div></div><div class="step"><div><h3>Acepta</h3><p>Puedes volver al campeonato desde el nuevo icono.</p></div></div></div>`)}</div><div class="section-space">${notice('','En este prototipo','La opción de instalación es ilustrativa. La compatibilidad real se comprobaría en la implementación.')}</div>`;
